pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const fileInput=document.getElementById("file-input"),uploadOverlay=document.getElementById("upload-overlay"),chatMessages=document.getElementById("chat-messages"),chatInput=document.getElementById("chat-input"),sendBtn=document.getElementById("send-btn");let documentText="",sentences=[];function handleSend(){const e=chatInput.value.trim();e&&(addMessage("user",e),chatInput.value="",setTimeout(()=>{addMessage("bot",findAnswer(e))},600))}function findAnswer(e){const t=e.toLowerCase().split(/\s+/).filter(e=>e.length>3);let n=0,s="I couldn't find a specific section matching your question. Could you try rephrasing or asking about a different topic?";return 0===t.length?"Please ask a more specific question.":(sentences.forEach(e=>{const a=e.toLowerCase();let o=0;t.forEach(e=>{a.includes(e)&&o++}),o>n&&(n=o,s=e.trim())}),s)}function addMessage(e,t){const n=document.createElement("div");n.className=`message ${e}`,n.innerText=t,chatMessages.appendChild(n),chatMessages.scrollTop=chatMessages.scrollHeight}function downloadChat(){const e=chatMessages.innerText,t=new Blob([e],{type:"text/plain"}),n=URL.createObjectURL(t),s=document.createElement("a");s.href=n,s.download="pdfindi_chat_transcript.txt",s.click()}fileInput.onchange=async e=>{const t=e.target.files[0];if(t){uploadOverlay.style.display="none";try{const e=await t.arrayBuffer(),n=await pdfjsLib.getDocument(e).promise;for(let e=1;e<=n.numPages;e++){const t=await n.getPage(e),s=(await t.getTextContent()).items.map(e=>e.str).join(" ");documentText+=s+" "}sentences=documentText.match(/[^.!?]+[.!?]+/g)||[],addMessage("bot",`Indexed ${sentences.length} sentences. I'm ready for your questions!`)}catch(e){alert("Error indexing PDF."),uploadOverlay.style.display="flex"}}},sendBtn.onclick=handleSend,chatInput.onkeypress=e=>{"Enter"===e.key&&handleSend()};